sidebar5=function(){const navitems=state.mode==='platform'?destinations.filter(d=>d[0]==='dashboard'||d[4].some(id=>modules.some(m=>m.id===id&&allowedModule(m)))).map(d=>{const first=d[4].find(id=>modules.some(m=>m.id===id&&allowedModule(m)));const active=d[0]==='dashboard'?state.page==='dashboard':state.page==='module'&&d[4].includes(v4.module);return `<button class="side-link ${active?'active':''}" data-action="${d[0]==='dashboard'?'v4-home':'v4-module'}" ${first?`data-id="${first}"`:''} title="${t(d[1],d[2])}">${icon(d[3])}<span>${t(d[1],d[2])}</span></button>`;}).join('')+(me().super?`<button class="side-link ${state.page==='workrules'?'active':''}" data-action="nav" data-page="workrules" title="${t('Aturan Pekerjaan','Work Rules')}">${icon('settings')}<span>${t('Aturan Pekerjaan','Work Rules')}</span></button>`:''):oldV4.nav().filter(([p])=>p!=='logs').map(([p,i])=>`<button class="side-link ${state.page===p?'active':''}" data-action="nav" data-page="${p}" title="${pages()[p]}">${icon(i)}<span>${pages()[p]}</span></button>`).join('');return `<aside class="side5 ${v5.collapsed?'small':''}" aria-label="${t('Navigasi utama','Main navigation')}"><div class="side-brand"><span class="mark">RM</span><strong>RILIS MUSIK</strong></div><button class="collapse-side" data-action="v5-collapse" aria-label="${t(v5.collapsed?'Perluas sidebar':'Perkecil sidebar',v5.collapsed?'Expand sidebar':'Collapse sidebar')}" title="${t(v5.collapsed?'Perluas sidebar':'Perkecil sidebar',v5.collapsed?'Expand sidebar':'Collapse sidebar')}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16m${v5.collapsed?'4-11 3 3-3 3':'7-11-3 3 3 3'}"/></svg></button><div class="side-mode">${modeControl6()}<button class="rail-mode" data-action="v6-mode" title="${state.mode==='platform'?'Platform → Staff':'Staff → Platform'}">${state.mode==='platform'?'P':'S'}</button></div><div class="side-scroll">${navitems}</div><div class="side-person">${avatar(me())}<div><small>${t('Halo,','Hello,')}</small><strong>${me().name}</strong><small>${personLabel(me())}</small></div></div></aside>`;};
modulePage=function(){const html=base6.modulePage(),box=document.createElement('div');box.innerHTML=html;const dest=destinations.find(d=>d[4].includes(v4.module));if(dest){box.querySelector('.module-content aside')?.remove();box.querySelector('.module-intro')?.insertAdjacentHTML('beforebegin',`<nav class="module-tabs" aria-label="${t('Bagian modul','Module sections')}">${dest[4].map(id=>modules.find(m=>m.id===id&&allowedModule(m))).filter(Boolean).map(m=>`<button data-action="v4-module" data-id="${m.id}" class="${m.id===v4.module?'active':''}">${L(m.title)}</button>`).join('')}${dest[0]==='cms'&&me().super?`<button data-action="nav" data-page="logs">${t('Riwayat simulasi','Simulation history')}</button>`:''}</nav>`);}return box.innerHTML;};
function active6(){return [...operationalTasks().map(x=>({...x,type:'task'})),...(me().super?data.ops.filter(x=>['pending','approved'].includes(x.status)).map(x=>({...x,type:'op',stage:x.status==='approved'?'approval':'queued'})):[])];}
function filterItems6(type){const all=active6();if(type==='believe')return all.filter(x=>x.type==='task'&&x.stage==='believe');if(type==='attention')return all.filter(x=>x.type==='task'&&taskAttention(x));return type==='queued'?all.filter(x=>x.stage==='queued'):type==='active'?all.filter(x=>x.stage!=='queued'):type==='waiting'?all.filter(x=>x.stage!=='queued'&&waiting(x)):all;}
function statCards6(){const done=todayRecords().filter(x=>me().super||x.staff===me().id).length;return `<section class="five-stats" aria-label="${t('Ringkasan pekerjaan','Work summary')}">${[['total',t('Total Pekerjaan','Total Work'),active6().length,t('Pekerjaan aktif','Active work')],['queued',t('Antrean Baru','New Queue'),filterItems6('queued').length,t('Belum ditangani','Awaiting handling')],['active',t('Dalam Penanganan','In Progress'),filterItems6('active').length,t('Tindakan sudah tercatat','Actions recorded')],['waiting',t('Menunggu Pihak Lain','Waiting on Others'),filterItems6('waiting').length,t('Bagian dari penanganan','Included in progress')],['done',t('Selesai Hari Ini','Completed Today'),done,t('Tahapan selesai','Completed stages')]].map(([id,label,n,sub],i)=>`<button data-action="v6-filter" data-id="${id}" class="stat6 ${i===0?'featured':''} ${v6.filter===id?'selected':''}"><span>${label}</span><i>↗</i><strong>${n}</strong><small>${sub}</small></button>`).join('')}</section>`;}
function filtered6(){if(!v6.filter)return '';const done=v6.filter==='done',items=done?todayRecords().filter(x=>me().super||x.staff===me().id):filterItems6(v6.filter);return `<section class="panel filtered6"><div class="panel-head"><div><h2>${t('Hasil filter','Filtered work')} · ${items.length}</h2><p>${t('Cakupan akun saat ini · Ringkasan Platform tidak berubah.','Current account scope · Platform Summary is unchanged.')}</p></div>${btn(t('Hapus filter','Clear filter'),'v6-clear','','text')}</div><div class="body">${items.map(x=>done?`<div class="row"><strong>${esc(x.title)}</strong><small>${person(x.staff).name} · ${x.time} · ${t('Tahapan selesai','Stage completed')}</small></div>`:x.type==='op'?opRows([x]):`<button class="queued-item" data-action="task" data-id="${x.id}"><span><strong>${esc(splitLabel(x.title))}</strong><small>${x.id} · ${esc(x.label)} · ${stageName(x.stage)}</small></span>${icon('arrow')}</button>`).join('')||empty(t('Tidak ada pekerjaan dalam filter ini','No work in this filter'))}</div></section>`;}
function taskStats6(){const a=active6(),q=a.filter(x=>x.stage==='queued').length,p=a.length-q;return `<section class="panel task-stats6"><div class="spread"><h2>${t('Statistik Pekerjaan Saya','My Work Statistics')}</h2><small>${t('Saat ini','Current')}</small></div><small>${t('Dalam cakupan role · antrean dapat dibagi dengan staf lain','Within role scope · queues may be shared with other staff')}</small><strong>${a.length}</strong><div class="tick-track" role="img" aria-label="${q} ${t('antrean','queued')}, ${p} ${t('dalam penanganan','in progress')}">${Array.from({length:50},(_,i)=>`<i class="${i/50<(a.length?q/a.length:0)?'queued':'handling'}"></i>`).join('')}</div><div class="legend"><span><i style="background:var(--accent)"></i>${q} ${t('Antrean','Queued')}</span><span><i style="background:#9caac8"></i>${p} ${t('Dalam penanganan','In progress')}</span></div></section>`;}
function insights6(){const waitingItems=operationalTasks().filter(x=>x.stage==='believe'),late=operationalTasks().filter(taskAttention),done=todayRecords().filter(x=>me().super||x.staff===me().id);const content=[[String(waitingItems.length),t('Menunggu respons distributor','Awaiting distributor response'),t('Periksa catatan tindak lanjut sebelum menghubungi kembali.','Review follow-up records before contacting again.'),'believe'],[String(late.length),t('Pekerjaan perlu tindak lanjut','Work needs follow-up'),t('Berdasarkan tenggat tahap dan tanggal skenario, bukan skor staf.','Based on stage deadlines and the scenario date, not staff ratings.'),'attention'],[String(done.length),t('Tahapan selesai hari ini','Stages completed today'),t('Hasil yang tercatat dapat ditelusuri. Jumlah bukan ukuran kualitas tunggal.','Recorded outcomes are traceable. Volume alone does not measure quality.'),'done']];const x=content[v6.insight];return `<section class="insights6"><div class="insight-tag">${icon('spark')}${t('Wawasan','Insights')}</div><strong>${x[0]}</strong><h2>${x[1]}</h2><p>${x[2]}</p>${btn(t('Lihat dasar data','View supporting data'),'v6-filter',`data-id="${x[3]}"`,'text')}<small>${date(day())} · ${t('Data simulasi','Simulated data')}</small><div class="insight-pages">${content.map((_,i)=>`<button data-action="v6-insight" data-id="${i}" class="${i===v6.insight?'active':''}" aria-label="${t('Wawasan','Insight')} ${i+1}" aria-pressed="${i===v6.insight}"></button>`).join('')}</div></section>`;}
function flow6(){const daily=v6.flow==='week',labels=daily?['14','15','16','17','18']:[t('Jul','Jul'),t('Agu','Aug')],incoming=daily?[8,5,9,6,7]:[82,94],finished=daily?[6,7,6,9,10]:[76,88],max=Math.max(...incoming,...finished);return `<section class="panel flow6"><div class="spread"><h2>${t('Arus Pekerjaan','Work Flow')}</h2><select id="flow-period" aria-label="${t('Periode arus pekerjaan','Work flow period')}"><option value="week" ${daily?'selected':''}>${t('Minggu contoh','Sample week')}</option><option value="months" ${!daily?'selected':''}>${t('Dua bulan','Two months')}</option></select></div><p>${t('Contoh agregat platform · satuan tahapan · data simulasi','Sample platform aggregate · stage counts · simulated data')}</p><div class="flow-chart">${labels.map((l,i)=>`<div class="flow-col"><div class="flow-pair"><span style="height:${incoming[i]/max*100}%" title="${t('Masuk','Incoming')}: ${incoming[i]}"><b>${incoming[i]}</b></span><span class="${i===labels.length-1?'hatched':''}" style="height:${finished[i]/max*100}%" title="${t('Selesai','Completed')}: ${finished[i]}"><b>${finished[i]}</b></span></div><small>${l}${daily?' Sep':''}</small></div>`).join('')}</div><div class="legend"><span><i style="background:var(--hover)"></i>${t('Masuk','Incoming')}</span><span><i style="background:var(--accent)"></i>${t('Selesai','Completed')}</span></div><small>${t('Penyelesaian dapat berasal dari antrean periode sebelumnya.','Completions may come from prior-period queues.')}</small></section>`;}
const platformData6=[['revenue','Pendapatan Layanan','Service Revenue',1120000,1000000,true,'Agustus / Juli 2026','August / July 2026'],['royalty','Pendapatan Royalti','Royalty Income',151641563,130000000,true,'Laporan Juni / Mei 2026','June / May 2026 reports'],['labels','Total Label','Total Labels',1772,1722,false,'Akhir Agustus / Juli 2026','End of August / July 2026'],['artists','Total Artis','Total Artists',6756,6645,false,'Akhir Agustus / Juli 2026','End of August / July 2026'],['releases','Total Rilisan','Total Releases',17931,17671,false,'Akhir Agustus / Juli 2026','End of August / July 2026'],['members','Label Aktif','Active Labels',171,167,false,'Akhir Agustus / Juli 2026','End of August / July 2026']];
function compareCurve6(up,id){return `<svg class="compare-curve" viewBox="0 0 300 150" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="fill-${id}" x2="0" y2="1"><stop stop-color="var(--accent)" stop-opacity=".15"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient><pattern id="dots-${id}" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="white" opacity=".6"/></pattern></defs><path d="M0 125 C90 125 115 110 160 70 S225 25 300 25 L300 150 L0 150Z" fill="url(#fill-${id})"/><path d="M0 125 C90 125 115 110 160 70 S225 25 300 25" fill="none" stroke="var(--accent)" stroke-width="2" opacity=".65"/><path d="M160 0V150" stroke="var(--muted)" stroke-dasharray="4 6" opacity=".25"/><circle cx="160" cy="70" r="4" fill="var(--surface)" stroke="var(--accent)" stroke-width="2"/><rect x="170" y="90" width="130" height="60" fill="url(#dots-${id})"/></svg>`;}
function platformCards6(){return `<section class="platform6"><div class="spread"><h2>${t('Ringkasan Platform','Platform Summary')}</h2><small>${t('Dua periode pembanding · data simulasi','Two comparison periods · simulated data')}</small></div><div class="platform6-grid">${me().super?`<article class="withdraw6"><div class="spread"><h3>${t('Penarikan periode ini','Period Withdrawals')}</h3>${btn('···','v6-metric','data-id="withdraw" aria-label="Detail"','text')}</div><small>${t('1–18 September / Agustus 2026','September / August 1–18, 2026')} · ${t('rentang setara','matched dates')}</small><div class="withdraw-value"><strong>${money(99215767)}</strong><span>↓ ${t('17,3%','17.3%')}</span></div><div class="payout-line"><span>${t('Sudah dibayar','Paid')}</span><strong>${money(75000000)}</strong></div><div class="payout-track"><i style="width:75.6%"></i></div><div class="payout-line muted"><span>${t('Belum dibayar','Unpaid')}</span><strong>${money(24215767)}</strong></div><small>${t('Jendela pencairan 15–20 · perubahan nominal bukan penilaian kinerja','Payout window 15–20 · amount changes are not performance ratings')}</small></article>`:''}${platformData6.filter(x=>x[0]!=='royalty'||me().super).map(x=>{const pct=(x[3]-x[4])/x[4]*100;return `<button class="compare6" data-action="v6-metric" data-id="${x[0]}"><h3>${t(x[1],x[2])}</h3>${compareCurve6(pct>=0,x[0])}<div><strong>${x[5]?money(x[3]):fmt(x[3])}</strong><p><span class="change-pill">↗</span> ${new Intl.NumberFormat(state.lang==='id'?'id-ID':'en-US',{maximumFractionDigits:1}).format(pct)}% <small>${t('vs bulan sebelumnya','vs previous month')}</small></p><small>${t(x[6],x[7])}</small></div></button>`;}).join('')}</div></section>`;}
dashboard=function(){const box=document.createElement('div');box.innerHTML=base6.dashboard();box.querySelector('.operational-strip')?.remove();box.querySelector('[data-card=summary]')?.remove();const grid=box.querySelector('.dashboard-grid'),my=grid.querySelector('[data-card=mywork]');my.querySelector('h2').textContent=t('Pekerjaan Saya','My Work');const wrap=document.createElement('div');wrap.className='my-work-stack span-6';my.before(wrap);wrap.append(my);wrap.insertAdjacentHTML('beforeend',taskStats6());const progressCard=grid.querySelector('[data-card=progress]');progressCard.querySelector('h2').textContent=t('Dalam Penanganan','In Progress');const activity=grid.querySelector('[data-card=activity]');activity.remove();grid.insertAdjacentHTML('afterend',`<div class="analysis6">${flow6()}${insights6()}</div>${platformCards6()}<section class="activity6">${activity.outerHTML}</section>`);const alert=box.querySelector('.focus-banner,.calm-banner');alert.insertAdjacentHTML('afterend',statCards6()+filtered6());if(v6.filter){grid.hidden=true;}return box.innerHTML;};
