searchModal=function(){base6.searchModal();const body=$('#dialog .dialog-body').innerHTML;$('#dialog').close();$('#dialog').classList.remove('search-dialog');$('#dialog').innerHTML='';closePop();v5.pop='search';$('.header').insertAdjacentHTML('beforeend',`<section id="header-popover" class="header-popover search-popover" aria-label="${t('Pencarian cepat','Quick search')}"><div class="popover-body">${body}</div></section>`);$('#search-input').focus();};
render=function(){base6.render();$('.header-left').innerHTML=`<button class="search-bar6" data-action="search" aria-label="${t('Cari menu atau pekerjaan','Search menus or work')}">${icon('search')}<span>${t('Cari menu atau pekerjaan…','Search menus or work…')}</span><kbd>⌘ / Ctrl K</kbd></button>`;$('.tools .search-trigger')?.remove();$('.version-pill').textContent='V6';$('.footer span').textContent='RILIS MUSIK · V6';document.title='Rilis Musik · V6';};
