handleAction=async function(b){const a=b.dataset.action,id=b.dataset.id;if(a==='v6-mode'){const fake=document.createElement('button');fake.dataset.action='mode';fake.dataset.mode=state.mode==='platform'?'staff':'platform';return handleAction(fake);}if(a==='v6-filter'){v6.filter=id;render();$('.filtered6')?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}if(a==='v6-clear'){v6.filter=null;render();return;}if(a==='v6-insight'){v6.insight=Number(id);const y=scrollY;render();scrollTo(0,y);return;}if(a==='v6-breakdown'){$('.earnings6')?.nextElementSibling?.scrollIntoView({block:'start',behavior:'smooth'});return;}if(a==='v6-metric'){const x=platformData6.find(x=>x[0]===id);modal(x?t(x[1],x[2]):t('Penarikan periode ini','Period withdrawals'),x?`<p>${t(x[6],x[7])}</p><div class="row"><span>${t('Periode saat ini','Current period')}</span><strong>${x[5]?money(x[3]):fmt(x[3])}</strong></div><div class="row"><span>${t('Periode sebelumnya','Previous period')}</span><strong>${x[5]?money(x[4]):fmt(x[4])}</strong></div><p class="scope-note">${t('Perubahan = (nilai saat ini − sebelumnya) / sebelumnya. Kurva hanya ilustrasi arah perbandingan dua periode, bukan tren harian. Data simulasi.','Change = (current − previous) / previous. The curve illustrates the comparison direction, not a daily trend. Simulated data.')}</p>`:`<p>${t('1–18 September dibanding 1–18 Agustus 2026.','September 1–18 compared with August 1–18, 2026.')}</p><div class="row"><span>${t('Permintaan periode ini','Current requests')}</span><strong>${money(99215767)}</strong></div><div class="row"><span>${t('Permintaan pembanding','Comparison requests')}</span><strong>${money(120000000)}</strong></div><p>${t('Dibayar','Paid')}: ${money(75000000)} · ${t('Belum dibayar','Unpaid')}: ${money(24215767)}</p><p class="scope-note">${t('Data contoh keuangan terpisah dari antrean demonstrasi. Tidak melakukan pembayaran nyata.','Financial sample data is separate from the demonstration queue. No real payments.')}</p>`);return;}if(a==='mode')v6.filter=null;if(a==='search'){closePop();searchModal();return;}return base6.handleAction(b);};
