guide=function(){modal(t('Selamat datang di V6','Welcome to V6'),`<p class="reflection">${t('Ringkasan lebih jelas. Detail pekerjaan lebih dekat.','Clearer summaries. Work details closer at hand.')}</p><ol class="guide-list"><li>${t('Klik salah satu dari lima ringkasan untuk menyaring pekerjaan di Dashboard. Hapus filter untuk kembali.','Select one of the five summaries to filter Dashboard work. Clear the filter to return.')}</li><li>${t('Cari menu atau pekerjaan dari header. Gunakan Ctrl / ⌘ K, panah, Enter, dan Escape.','Search menus or work from the header. Use Ctrl / ⌘ K, arrow keys, Enter and Escape.')}</li><li>${t('Perkecil sidebar melalui tombol di samping logo. Beralih Platform–Staff dari bagian atas sidebar.','Collapse the sidebar beside the logo. Switch Platform–Staff at the top of the sidebar.')}</li><li>${t('Telusuri Wawasan, Arus Pekerjaan, serta kartu platform untuk melihat dasar data simulasi.','Explore Insights, Work Flow and platform cards to inspect the simulated evidence.')}</li></ol><p class="scope-note">${t('Seluruh data, pesan, ulasan AI, dan dokumen adalah simulasi lokal.','All records, messages, AI reviews and documents are local simulations.')}</p>`);};
